                    use braincrawl_cli::content::ArtifactListing;
                    let mut results = match store.list_artifacts(
                        &args.id,
                        args.role.as_deref(),
                        args.all_versions,
                    )? {
                        ArtifactListing::Held(results) => results,
                        ArtifactListing::UnknownWork => {
